import java.io.InputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Random;

public class Main {

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int count = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private byte read() throws IOException {
            if (ptr >= count) {
                count = in.read(buffer, 0, buffer.length);
                if (count <= 0) return -1;
                ptr = 0;
            }
            return buffer[ptr++];
        }

        public long nextLong() throws IOException {
            byte b = read();
            while (b <= ' ' && b != -1) {
                b = read();
            }
            if (b == -1) return 0;
            boolean neg = false;
            if (b == '-') {
                neg = true;
                b = read();
            }
            long res = 0;
            while (b >= '0' && b <= '9') {
                res = res * 10 + (b - '0');
                b = read();
            }
            return neg ? -res : res;
        }

        public int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Treap {
        int maxNodes;
        long[] key;
        int[] priority;
        int[] count;
        int[] size;
        int[] left;
        int[] right;
        int root = 0;
        int nodeCount = 0;
        Random rng = new Random(1337);

        public Treap(int n) {
            this.maxNodes = n + 5;
            key = new long[maxNodes];
            priority = new int[maxNodes];
            count = new int[maxNodes];
            size = new int[maxNodes];
            left = new int[maxNodes];
            right = new int[maxNodes];
        }

        private void update(int u) {
            size[u] = count[u] + size[left[u]] + size[right[u]];
        }

        private int rotateRight(int y) {
            int x = left[y];
            left[y] = right[x];
            right[x] = y;
            update(y);
            update(x);
            return x;
        }

        private int rotateLeft(int x) {
            int y = right[x];
            right[x] = left[y];
            left[y] = x;
            update(x);
            update(y);
            return y;
        }

        public void insert(long val) {
            root = insert(root, val);
        }

        private int insert(int u, long val) {
            if (u == 0) {
                nodeCount++;
                key[nodeCount] = val;
                priority[nodeCount] = rng.nextInt();
                count[nodeCount] = 1;
                size[nodeCount] = 1;
                left[nodeCount] = 0;
                right[nodeCount] = 0;
                return nodeCount;
            }
            if (key[u] == val) {
                count[u]++;
                size[u]++;
                return u;
            }
            if (val < key[u]) {
                left[u] = insert(left[u], val);
                if (priority[left[u]] > priority[u]) {
                    u = rotateRight(u);
                }
            } else {
                right[u] = insert(right[u], val);
                if (priority[right[u]] > priority[u]) {
                    u = rotateLeft(u);
                }
            }
            update(u);
            return u;
        }

        public int countLessOrEqual(long val) {
            return countLessOrEqual(root, val);
        }

        private int countLessOrEqual(int u, long val) {
            if (u == 0) return 0;
            if (key[u] <= val) {
                return size[left[u]] + count[u] + countLessOrEqual(right[u], val);
            } else {
                return countLessOrEqual(left[u], val);
            }
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = scanner.nextInt();
        Treap treap = new Treap(n);

        long lastP = 0;
        for (int i = 0; i < n; i++) {
            long x = scanner.nextLong();
            long y = scanner.nextLong();

            long xr = x + lastP;
            long yr = y + lastP;

            long distSq = xr * xr + yr * yr;

            int p = treap.countLessOrEqual(distSq);
            out.println(p);

            treap.insert(distSq);
            lastP = p;
        }

        out.flush();
    }
}
